export interface ConnectorConfig {
  githubOwner: string
  githubRepo: string
  githubToken: string
  zendeskSubdomain: string
  zendeskToken: string
  fetch?: typeof fetch
}

export interface ZendeskTicketCreatedPayload {
  detail: {
    subject: string
    description: string
    id: string | number
  }
  subject: string
}

export interface HandleResult {
  githubIssueNumber: number
  githubIssueUrl: string
  zendeskCommentId: number
}

async function postJson<T>(
  url: string,
  body: unknown,
  token: string,
  fetchFn: typeof fetch,
): Promise<T> {
  const response = await fetchFn(url, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${token}`,
      Accept: 'application/vnd.github.v3+json',
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body),
  })

  if (!response.ok) {
    throw new Error(`GitHub API error: ${response.status} ${response.statusText} for ${url}`)
  }

  return response.json() as Promise<T>
}

async function postZendeskComment(
  url: string,
  body: unknown,
  token: string,
  fetchFn: typeof fetch,
): Promise<{ comment: { id: number } }> {
  const response = await fetchFn(url, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${token}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body),
  })

  if (!response.ok) {
    throw new Error(`Zendesk API error: ${response.status} ${response.statusText} for ${url}`)
  }

  return response.json() as Promise<{ comment: { id: number } }>
}

export async function handle(
  payload: ZendeskTicketCreatedPayload,
  config: ConnectorConfig,
): Promise<HandleResult> {
  const fetchFn = config.fetch ?? fetch

  if (!payload.detail?.subject) {
    throw new Error('Missing required field: detail.subject')
  }
  if (!payload.detail?.description) {
    throw new Error('Missing required field: detail.description')
  }
  if (payload.detail?.id === undefined || payload.detail?.id === null) {
    throw new Error('Missing required field: detail.id')
  }

  const ticketId = String(payload.detail.id)
  const title = payload.detail.subject
  const body = payload.detail.description
  const labels = [`zendesk-ticket:${ticketId}`]

  const githubUrl = `https://api.github.com/repos/${config.githubOwner}/${config.githubRepo}/issues`
  const githubResponse = await postJson<{ number: number; html_url: string }>(
    githubUrl,
    { title, body, labels },
    config.githubToken,
    fetchFn,
  )

  const zendeskUrl = `https://${config.zendeskSubdomain}.zendesk.com/api/v2/tickets/${ticketId}/comments.json`
  const commentBody = `GitHub issue created: ${githubResponse.html_url}`
  const zendeskResponse = await postZendeskComment(
    zendeskUrl,
    { body: commentBody },
    config.zendeskToken,
    fetchFn,
  )

  return {
    githubIssueNumber: githubResponse.number,
    githubIssueUrl: githubResponse.html_url,
    zendeskCommentId: zendeskResponse.comment.id,
  }
}

import { describe, it, expect, vi } from 'vitest'
import { handle, ConnectorConfig, ZendeskTicketCreatedPayload } from './connector'
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall,
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      githubOwner: 'octocat',
      githubRepo: 'Hello-World',
      githubToken: 'gh_test_token',
      zendeskSubdomain: 'testsubdomain',
      zendeskToken: 'zd_test_token',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as ZendeskTicketCreatedPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.githubIssueNumber).toBe(1347)
    expect(result.githubIssueUrl).toBe('https://github.com/octocat/Hello-World/issues/1347')
    expect(result.zendeskCommentId).toBe(12345)
  })
})

describe('handle', () => {
  const baseConfig: ConnectorConfig = {
    githubOwner: 'octocat',
    githubRepo: 'Hello-World',
    githubToken: 'gh_test_token',
    zendeskSubdomain: 'testsubdomain',
    zendeskToken: 'zd_test_token',
  }

  it('creates GitHub issue and posts Zendesk comment on happy path', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.url.includes('/repos/octocat/Hello-World/issues')) {
        return jsonResponse({ number: 42, html_url: 'https://github.com/octocat/Hello-World/issues/42' }, 201)
      }
      if (req.url.includes('/tickets/14038/comments.json')) {
        return jsonResponse({ comment: { id: 999, body: '', author_id: 1, created_at: '2025-01-14T20:30:00Z' } }, 201)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const payload: ZendeskTicketCreatedPayload = {
      detail: {
        subject: 'Test ticket subject',
        description: 'Test ticket description',
        id: '14038',
      },
      subject: 'zen:ticket:14038',
    }

    const result = await handle(payload, { ...baseConfig, fetch })

    expect(result.githubIssueNumber).toBe(42)
    expect(result.githubIssueUrl).toBe('https://github.com/octocat/Hello-World/issues/42')
    expect(result.zendeskCommentId).toBe(999)

    expect(calls).toHaveLength(2)

    const githubCall = calls[0]
    expect(githubCall.method).toBe('POST')
    expect(githubCall.url).toBe('https://api.github.com/repos/octocat/Hello-World/issues')
    expect(githubCall.json).toEqual({
      title: 'Test ticket subject',
      body: 'Test ticket description',
      labels: ['zendesk-ticket:14038'],
    })
    expect(githubCall.headers.get('authorization')).toBe('Bearer gh_test_token')
    expect(githubCall.headers.get('accept')).toBe('application/vnd.github.v3+json')

    const zendeskCall = calls[1]
    expect(zendeskCall.method).toBe('POST')
    expect(zendeskCall.url).toBe('https://testsubdomain.zendesk.com/api/v2/tickets/14038/comments.json')
    expect(zendeskCall.json).toEqual({
      body: 'GitHub issue created: https://github.com/octocat/Hello-World/issues/42',
    })
    expect(zendeskCall.headers.get('authorization')).toBe('Bearer zd_test_token')
  })

  it('throws when detail.subject is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = {
      detail: {
        description: 'desc',
        id: '123',
      },
      subject: 'zen:ticket:123',
    } as unknown as ZendeskTicketCreatedPayload

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: detail.subject')
  })

  it('throws when detail.description is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = {
      detail: {
        subject: 'subj',
        id: '123',
      },
      subject: 'zen:ticket:123',
    } as unknown as ZendeskTicketCreatedPayload

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: detail.description')
  })

  it('throws when detail.id is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = {
      detail: {
        subject: 'subj',
        description: 'desc',
      },
      subject: 'zen:ticket:123',
    } as unknown as ZendeskTicketCreatedPayload

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: detail.id')
  })

  it('throws on non-2xx GitHub response with status and endpoint', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ message: 'Validation Failed' }, 422))
    const payload: ZendeskTicketCreatedPayload = {
      detail: { subject: 'subj', description: 'desc', id: '123' },
      subject: 'zen:ticket:123',
    }

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow(
      'GitHub API error: 422 Unprocessable Entity for https://api.github.com/repos/octocat/Hello-World/issues',
    )
  })

  it('throws on non-2xx Zendesk response with status and endpoint', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.url.includes('/repos/octocat/Hello-World/issues')) {
        return jsonResponse({ number: 1, html_url: 'https://github.com/octocat/Hello-World/issues/1' }, 201)
      }
      return jsonResponse({ error: 'Forbidden' }, 403)
    })

    const payload: ZendeskTicketCreatedPayload = {
      detail: { subject: 'subj', description: 'desc', id: '123' },
      subject: 'zen:ticket:123',
    }

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow(
      'Zendesk API error: 403 Forbidden for https://testsubdomain.zendesk.com/api/v2/tickets/123/comments.json',
    )
  })

  it('uses detail.id for label even when subject has different format', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.url.includes('/repos/octocat/Hello-World/issues')) {
        return jsonResponse({ number: 5, html_url: 'https://github.com/octocat/Hello-World/issues/5' }, 201)
      }
      return jsonResponse({ comment: { id: 1, body: '', author_id: 1, created_at: '2025-01-14T20:30:00Z' } }, 201)
    })

    const payload: ZendeskTicketCreatedPayload = {
      detail: { subject: 'Real subject', description: 'Real description', id: '99999' },
      subject: 'zen:ticket:different',
    }

    await handle(payload, { ...baseConfig, fetch })

    const githubCall = calls[0]
    expect(githubCall.json).toEqual({
      title: 'Real subject',
      body: 'Real description',
      labels: ['zendesk-ticket:99999'],
    })
  })
})

